export interface AppEmbedData {
  /** The type of Wix App content being embedded. */
  type: AppEmbedData_AppType;
  /** The ID of the embedded content. */
  itemId?: string;
  /** The name of the embedded content. */
  name?: string;
  /**
   * Deprecated: Use `image` instead.
   *
   * @deprecated
   */
  imageSrc?: string;
  /** The URL for the embedded content. */
  url?: string;
  /** An image for the embedded content. */
  image?: Media;
  /** Data for embedded Wix Bookings content. */
  bookingData?: AppEmbedData_BookingData | undefined;
  /** Data for embedded Wix Events content. */
  eventData?: AppEmbedData_EventData | undefined;
  /** Whether to hide the image. */
  hideImage?: boolean;
  /** Whether to hide the title. */
  hideTitle?: boolean;
  /** Whether to hide the price. */
  hidePrice?: boolean;
  /** Whether to hide the description (Event and Booking). */
  hideDescription?: boolean;
  /** Whether to hide the date and time (Event). */
  hideDateTime?: boolean;
  /** Whether to hide the location (Event). */
  hideLocation?: boolean;
  /** Whether to hide the duration (Booking). */
  hideDuration?: boolean;
  /** Whether to hide the button. */
  hideButton?: boolean;
  /** Whether to hide the ribbon. */
  hideRibbon?: boolean;
  /** Button styling options. */
  buttonStyles?: AppEmbedData_ButtonStyles;
  /** Image styling options. */
  imageStyles?: AppEmbedData_ImageStyles;
  /** Ribbon styling options. */
  ribbonStyles?: AppEmbedData_RibbonStyles;
  /** Card styling options. */
  cardStyles?: AppEmbedData_CardStyles;
  /** Styling for the app embed's container. */
  containerData?: PluginContainerData;
  /** Pricing data for embedded Wix App content. */
  pricingData?: AppEmbedData_PricingData;
  /** Node animation. */
  animation?: Animation;
}

export function appEmbedData_AppTypeFromJSON(
  object: any
): AppEmbedData_AppType {
  switch (object) {
    case 0:
    case "PRODUCT":
      return AppEmbedData_AppType.PRODUCT;
    case 1:
    case "EVENT":
      return AppEmbedData_AppType.EVENT;
    case 2:
    case "BOOKING":
      return AppEmbedData_AppType.BOOKING;
    case -1:
    case "UNRECOGNIZED":
    default:
      return AppEmbedData_AppType.UNRECOGNIZED;
  }
}

export function appEmbedData_AppTypeToJSON(
  object: AppEmbedData_AppType
): string {
  switch (object) {
    case AppEmbedData_AppType.PRODUCT:
      return "PRODUCT";
    case AppEmbedData_AppType.EVENT:
      return "EVENT";
    case AppEmbedData_AppType.BOOKING:
      return "BOOKING";
    default:
      return "UNKNOWN";
  }
}

