const basePollData: object = {};

export const PollData = {
  fromJSON(object: any): PollData {
    const message = { ...basePollData } as PollData;
    message.containerData =
      object.containerData !== undefined && object.containerData !== null
        ? PluginContainerData.fromJSON(object.containerData)
        : undefined;
    message.poll =
      object.poll !== undefined && object.poll !== null
        ? PollData_Poll.fromJSON(object.poll)
        : undefined;
    message.layout =
      object.layout !== undefined && object.layout !== null
        ? PollData_Layout.fromJSON(object.layout)
        : undefined;
    message.design =
      object.design !== undefined && object.design !== null
        ? PollData_Design.fromJSON(object.design)
        : undefined;
    message.animation =
      object.animation !== undefined && object.animation !== null
        ? Animation.fromJSON(object.animation)
        : undefined;
    return message;
  },

  toJSON(message: PollData): unknown {
    const obj: any = {};
    message.containerData !== undefined &&
      (obj.containerData = message.containerData
        ? PluginContainerData.toJSON(message.containerData)
        : undefined);
    message.poll !== undefined &&
      (obj.poll = message.poll
        ? PollData_Poll.toJSON(message.poll)
        : undefined);
    message.layout !== undefined &&
      (obj.layout = message.layout
        ? PollData_Layout.toJSON(message.layout)
        : undefined);
    message.design !== undefined &&
      (obj.design = message.design
        ? PollData_Design.toJSON(message.design)
        : undefined);
    message.animation !== undefined &&
      (obj.animation = message.animation
        ? Animation.toJSON(message.animation)
        : undefined);
    return obj;
  },
};

const basePollData_Poll: object = {};

export const PollData_Poll = {
  fromJSON(object: any): PollData_Poll {
    const message = { ...basePollData_Poll } as PollData_Poll;
    message.id =
      object.id !== undefined && object.id !== null
        ? String(object.id)
        : undefined;
    message.title =
      object.title !== undefined && object.title !== null
        ? String(object.title)
        : undefined;
    message.creatorId =
      object.creatorId !== undefined && object.creatorId !== null
        ? String(object.creatorId)
        : undefined;
    message.image =
      object.image !== undefined && object.image !== null
        ? Media.fromJSON(object.image)
        : undefined;
    message.options = (object.options ?? []).map((e: any) =>
      PollData_Poll_Option.fromJSON(e)
    );
    message.settings =
      object.settings !== undefined && object.settings !== null
        ? PollData_Poll_Settings.fromJSON(object.settings)
        : undefined;
    return message;
  },

  toJSON(message: PollData_Poll): unknown {
    const obj: any = {};
    message.id !== undefined && (obj.id = message.id);
    message.title !== undefined && (obj.title = message.title);
    message.creatorId !== undefined && (obj.creatorId = message.creatorId);
    message.image !== undefined &&
      (obj.image = message.image ? Media.toJSON(message.image) : undefined);
    if (message.options) {
      obj.options = message.options.map((e) =>
        e ? PollData_Poll_Option.toJSON(e) : undefined
      );
    } else {
      obj.options = [];
    }
    message.settings !== undefined &&
      (obj.settings = message.settings
        ? PollData_Poll_Settings.toJSON(message.settings)
        : undefined);
    return obj;
  },
};

