/* eslint-disable */
import { Animation } from './animation.js';

import { TocData_ListStyle, TocData_Indentation } from './plugin_toc.enums.js';

/**
 * flynt-disable boolean-field-name-prefix
 * flynt-disable missing-array-limits
 * flynt-disable missing-string-validations
 */

export interface TocData {
  /** Heading levels included in the table of contents. Default: [1, 2, 3, 4, 5, 6]. */
  includedHeadings: number[];
  /** List style. Default: PLAIN. */
  listStyle: TocData_ListStyle;
  /** Optional override for the font size in pixels. */
  fontSize?: number;
  /** Optional override for the vertical spacing between items in pixels. */
  itemSpacing?: number;
  /** Optional override for the text color. */
  color?: string;
  /** Indentation style. Default: NESTED. */
  indentation: TocData_Indentation;
  /** Node animation. */
  animation?: Animation;
}

export function tocData_ListStyleFromJSON(object: any): TocData_ListStyle {
  switch (object) {
    case 0:
    case "PLAIN":
      return TocData_ListStyle.PLAIN;
    case 1:
    case "NUMBERED":
      return TocData_ListStyle.NUMBERED;
    case 2:
    case "LETTERS":
      return TocData_ListStyle.LETTERS;
    case 3:
    case "ROMAN":
      return TocData_ListStyle.ROMAN;
    case 4:
    case "BULLETED":
      return TocData_ListStyle.BULLETED;
    case 5:
    case "ALPHABETICAL_INDEX":
      return TocData_ListStyle.ALPHABETICAL_INDEX;
    case 6:
    case "ALPHABETICAL_INDEX_COMPACT":
      return TocData_ListStyle.ALPHABETICAL_INDEX_COMPACT;
    case -1:
    case "UNRECOGNIZED":
    default:
      return TocData_ListStyle.UNRECOGNIZED;
  }
}

export function tocData_ListStyleToJSON(object: TocData_ListStyle): string {
  switch (object) {
    case TocData_ListStyle.PLAIN:
      return "PLAIN";
    case TocData_ListStyle.NUMBERED:
      return "NUMBERED";
    case TocData_ListStyle.LETTERS:
      return "LETTERS";
    case TocData_ListStyle.ROMAN:
      return "ROMAN";
    case TocData_ListStyle.BULLETED:
      return "BULLETED";
    case TocData_ListStyle.ALPHABETICAL_INDEX:
      return "ALPHABETICAL_INDEX";
    case TocData_ListStyle.ALPHABETICAL_INDEX_COMPACT:
      return "ALPHABETICAL_INDEX_COMPACT";
    default:
      return "UNKNOWN";
  }
}

export function tocData_IndentationFromJSON(object: any): TocData_Indentation {
  switch (object) {
    case 0:
    case "NESTED":
      return TocData_Indentation.NESTED;
    case 1:
    case "FLAT":
      return TocData_Indentation.FLAT;
    case -1:
    case "UNRECOGNIZED":
    default:
      return TocData_Indentation.UNRECOGNIZED;
  }
}

export function tocData_IndentationToJSON(object: TocData_Indentation): string {
  switch (object) {
    case TocData_Indentation.NESTED:
      return "NESTED";
    case TocData_Indentation.FLAT:
      return "FLAT";
    default:
      return "UNKNOWN";
  }
}

const baseTocData: object = {
  includedHeadings: 0,
  listStyle: TocData_ListStyle.PLAIN,
  indentation: TocData_Indentation.NESTED,
};

export const TocData = {
  fromJSON(object: any): TocData {
    const message = { ...baseTocData } as TocData;
    message.includedHeadings = (object.includedHeadings ?? []).map((e: any) =>
      Number(e)
    );
    message.listStyle =
      object.listStyle !== undefined && object.listStyle !== null
        ? tocData_ListStyleFromJSON(object.listStyle)
        : TocData_ListStyle.PLAIN;
    message.fontSize =
      object.fontSize !== undefined && object.fontSize !== null
        ? Number(object.fontSize)
        : undefined;
    message.itemSpacing =
      object.itemSpacing !== undefined && object.itemSpacing !== null
        ? Number(object.itemSpacing)
        : undefined;
    message.color =
      object.color !== undefined && object.color !== null
        ? String(object.color)
        : undefined;
    message.indentation =
      object.indentation !== undefined && object.indentation !== null
        ? tocData_IndentationFromJSON(object.indentation)
        : TocData_Indentation.NESTED;
    message.animation =
      object.animation !== undefined && object.animation !== null
        ? Animation.fromJSON(object.animation)
        : undefined;
    return message;
  },

  toJSON(message: TocData): unknown {
    const obj: any = {};
    if (message.includedHeadings) {
      obj.includedHeadings = message.includedHeadings.map((e) => Math.round(e));
    } else {
      obj.includedHeadings = [];
    }
    message.listStyle !== undefined &&
      (obj.listStyle = tocData_ListStyleToJSON(message.listStyle));
    message.fontSize !== undefined && (obj.fontSize = message.fontSize);
    message.itemSpacing !== undefined &&
      (obj.itemSpacing = message.itemSpacing);
    message.color !== undefined && (obj.color = message.color);
    message.indentation !== undefined &&
      (obj.indentation = tocData_IndentationToJSON(message.indentation));
    message.animation !== undefined &&
      (obj.animation = message.animation
        ? Animation.toJSON(message.animation)
        : undefined);
    return obj;
  },
};
