export const TextStyle = {
  fromJSON(object: any): TextStyle {
    const message = { ...baseTextStyle } as TextStyle;
    message.textAlignment =
      object.textAlignment !== undefined && object.textAlignment !== null
        ? textStyle_TextAlignmentFromJSON(object.textAlignment)
        : TextStyle_TextAlignment.AUTO;
    message.lineHeight =
      object.lineHeight !== undefined && object.lineHeight !== null
        ? String(object.lineHeight)
        : undefined;
    return message;
  },

  toJSON(message: TextStyle): unknown {
    const obj: any = {};
    message.textAlignment !== undefined &&
      (obj.textAlignment = textStyle_TextAlignmentToJSON(
        message.textAlignment
      ));
    message.lineHeight !== undefined && (obj.lineHeight = message.lineHeight);
    return obj;
  },
};

const baseLink: object = { target: Link_Target.SELF };

