const baseGradient: object = { type: Gradient_Type.LINEAR };

export const Gradient = {
  fromJSON(object: any): Gradient {
    const message = { ...baseGradient } as Gradient;
    message.type =
      object.type !== undefined && object.type !== null
        ? gradient_TypeFromJSON(object.type)
        : Gradient_Type.LINEAR;
    message.stops = (object.stops ?? []).map((e: any) =>
      Gradient_Stop.fromJSON(e)
    );
    message.angle =
      object.angle !== undefined && object.angle !== null
        ? Number(object.angle)
        : undefined;
    message.centerX =
      object.centerX !== undefined && object.centerX !== null
        ? Number(object.centerX)
        : undefined;
    message.centerY =
      object.centerY !== undefined && object.centerY !== null
        ? Number(object.centerY)
        : undefined;
    return message;
  },

  toJSON(message: Gradient): unknown {
    const obj: any = {};
    message.type !== undefined &&
      (obj.type = gradient_TypeToJSON(message.type));
    if (message.stops) {
      obj.stops = message.stops.map((e) =>
        e ? Gradient_Stop.toJSON(e) : undefined
      );
    } else {
      obj.stops = [];
    }
    message.angle !== undefined && (obj.angle = message.angle);
    message.centerX !== undefined && (obj.centerX = message.centerX);
    message.centerY !== undefined && (obj.centerY = message.centerY);
    return obj;
  },
};

const baseGradient_Stop: object = {};

export const Gradient_Stop = {
  fromJSON(object: any): Gradient_Stop {
    const message = { ...baseGradient_Stop } as Gradient_Stop;
    message.color =
      object.color !== undefined && object.color !== null
        ? String(object.color)
        : undefined;
    message.position =
      object.position !== undefined && object.position !== null
        ? Number(object.position)
        : undefined;
    return message;
  },

  toJSON(message: Gradient_Stop): unknown {
    const obj: any = {};
    message.color !== undefined && (obj.color = message.color);
    message.position !== undefined && (obj.position = message.position);
    return obj;
  },
};
