import { Animation_Type, EntranceEffect_Type, LoopEffect_Type, PointerEffect_Type } from './animation.enums.js';
/* eslint-disable */
export interface Animation {
  /** Animation kind. */
  type: Animation_Type;
  /** Entrance animation, played once when the node first enters the viewport (VIEW). */
  entrance?: EntranceAnimation;
  /** Looping animation, repeated indefinitely while the node is on the page. When combined with entrance, the loop starts after the entrance finishes (VIEW). */
  loop?: LoopAnimation;
  /**
   * POINTER carries its fields directly on the union member in the JTD wall, hence
   * flat fields here (ts-proto camelCase must equal the JTD property names). A future
   * kind that also needs an `effect` field would contend for this JSON name.
   */
  effect?: PointerEffect;
  /** How quickly the node settles toward the pointer, in milliseconds (POINTER). */
  transitionDuration?: number;
}

export function animation_TypeFromJSON(object: any): Animation_Type {
  switch (object) {
    case 0:
    case "VIEW":
      return Animation_Type.VIEW;
    case 1:
    case "POINTER":
      return Animation_Type.POINTER;
    case -1:
    case "UNRECOGNIZED":
    default:
      return Animation_Type.UNRECOGNIZED;
  }
}

export function animation_TypeToJSON(object: Animation_Type): string {
  switch (object) {
    case Animation_Type.VIEW:
      return "VIEW";
    case Animation_Type.POINTER:
      return "POINTER";
    default:
      return "UNKNOWN";
  }
}

export interface EntranceAnimation {
  /** The entrance effect to play. */
  effect?: EntranceEffect;
  /** Effect duration in milliseconds. Each effect has its own default. */
  duration?: number;
  /** Delay before the effect starts, in milliseconds. */
  delay?: number;
}

export interface EntranceEffect {
  /** The entrance effect type. */
  type: EntranceEffect_Type;
  /** Direction the effect enters from. Allowed values depend on the effect type (e.g. TOP/RIGHT/BOTTOM/LEFT, the diagonals with or without CENTER, corners, HORIZONTAL/VERTICAL, CLOCKWISE/COUNTER_CLOCKWISE). */
  direction?: string;
  /** Clip-path shape: ELLIPSE, CIRCLE, RECTANGLE, or DIAMOND (SHAPE). */
  shape?: string;
  /** Motion style: GENTLE, MODERATE, or INTENSE. Only the effects that expose one accept it. */
  easing?: string;
}

