const baseAnimation: object = { type: Animation_Type.VIEW };

export const Animation = {
  fromJSON(object: any): Animation {
    const message = { ...baseAnimation } as Animation;
    message.type =
      object.type !== undefined && object.type !== null
        ? animation_TypeFromJSON(object.type)
        : Animation_Type.VIEW;
    message.entrance =
      object.entrance !== undefined && object.entrance !== null
        ? EntranceAnimation.fromJSON(object.entrance)
        : undefined;
    message.loop =
      object.loop !== undefined && object.loop !== null
        ? LoopAnimation.fromJSON(object.loop)
        : undefined;
    message.effect =
      object.effect !== undefined && object.effect !== null
        ? PointerEffect.fromJSON(object.effect)
        : undefined;
    message.transitionDuration =
      object.transitionDuration !== undefined &&
      object.transitionDuration !== null
        ? Number(object.transitionDuration)
        : undefined;
    return message;
  },

  toJSON(message: Animation): unknown {
    const obj: any = {};
    message.type !== undefined &&
      (obj.type = animation_TypeToJSON(message.type));
    message.entrance !== undefined &&
      (obj.entrance = message.entrance
        ? EntranceAnimation.toJSON(message.entrance)
        : undefined);
    message.loop !== undefined &&
      (obj.loop = message.loop
        ? LoopAnimation.toJSON(message.loop)
        : undefined);
    message.effect !== undefined &&
      (obj.effect = message.effect
        ? PointerEffect.toJSON(message.effect)
        : undefined);
    message.transitionDuration !== undefined &&
      (obj.transitionDuration = message.transitionDuration);
    return obj;
  },
};

