import { PluginContainerData, Link, Gradient } from './common.js';
import { Animation } from './animation.js';

import { ButtonData_Type, ButtonData_Styles_Background_Type } from './plugin_button.enums.js';

export interface ButtonData {
  /** Styling for the button's container. */
  containerData?: PluginContainerData;
  /** The button type. */
  type: ButtonData_Type;
  /** Styling for the button. */
  styles?: ButtonData_Styles;
  /** The text to display on the button. */
  text?: string;
  /** Button link details. */
  link?: Link;
  /** Node animation. */
  animation?: Animation;
}

export function buttonData_TypeFromJSON(object: any): ButtonData_Type {
  switch (object) {
    case 0:
    case "LINK":
      return ButtonData_Type.LINK;
    case 1:
    case "ACTION":
      return ButtonData_Type.ACTION;
    case -1:
    case "UNRECOGNIZED":
    default:
      return ButtonData_Type.UNRECOGNIZED;
  }
}

export function buttonData_TypeToJSON(object: ButtonData_Type): string {
  switch (object) {
    case ButtonData_Type.LINK:
      return "LINK";
    case ButtonData_Type.ACTION:
      return "ACTION";
    default:
      return "UNKNOWN";
  }
}

export interface ButtonData_Styles {
  /**
   * Deprecated: Use `borderWidth` and `borderRadius` instead.
   *
   * @deprecated
   */
  border?: ButtonData_Styles_Border;
  /**
   * Deprecated: Use `textColor`, `borderColor` and `backgroundColor` instead.
   *
   * @deprecated
   */
  colors?: ButtonData_Styles_Colors;
  /** Border width in pixels. */
  borderWidth?: number;
  /**
   * Deprecated: Use `borderWidth` for normal/hover states instead.
   *
   * @deprecated
   */
  borderWidthHover?: number;
  /** Border radius in pixels. */
  borderRadius?: number;
  /** Border color as a hexadecimal value. */
  borderColor?: string;
  /** Border color as a hexadecimal value (hover state). */
  borderColorHover?: string;
  /** Text color as a hexadecimal value. */
  textColor?: string;
  /** Text color as a hexadecimal value (hover state). */
  textColorHover?: string;
  /**
   * Deprecated: Use `background` instead.
   *
   * @deprecated
   */
  backgroundColor?: string;
  /**
   * Deprecated: Use `backgroundHover` instead.
   *
   * @deprecated
   */
  backgroundColorHover?: string;
  /** Button size option, one of `SMALL`, `MEDIUM` or `LARGE`. Defaults to `MEDIUM`. */
  buttonSize?: string;
  /** Background styling (color or gradient). */
  background?: ButtonData_Styles_Background;
  /** Background styling for hover state (color or gradient). */
  backgroundHover?: ButtonData_Styles_Background;
}

export interface ButtonData_Styles_Colors {
  /**
   * Deprecated: Use `textColor` in `styles` instead.
   *
   * @deprecated
   */
  text?: string;
  /**
   * Deprecated: Use `borderColor` in `styles` instead.
   *
   * @deprecated
   */
  border?: string;
  /**
   * Deprecated: Use `backgroundColor` in `styles` instead.
   *
   * @deprecated
   */
  background?: string;
}

export interface ButtonData_Styles_Border {
  /**
   * Deprecated: Use `borderWidth` in `styles` instead.
   *
   * @deprecated
   */
  width?: number;
  /**
   * Deprecated: Use `borderRadius` in `styles` instead.
   *
   * @deprecated
   */
  radius?: number;
}

/** Background styling (color or gradient) */
export interface ButtonData_Styles_Background {
  /** Background type. */
  type: ButtonData_Styles_Background_Type;
  /** Background color as a hexadecimal value. */
  color?: string;
  /** Gradient configuration. */
  gradient?: Gradient;
}

export function buttonData_Styles_Background_TypeFromJSON(
  object: any
): ButtonData_Styles_Background_Type {
  switch (object) {
    case 0:
    case "COLOR":
      return ButtonData_Styles_Background_Type.COLOR;
    case 1:
    case "GRADIENT":
      return ButtonData_Styles_Background_Type.GRADIENT;
    case -1:
    case "UNRECOGNIZED":
    default:
      return ButtonData_Styles_Background_Type.UNRECOGNIZED;
  }
}

export function buttonData_Styles_Background_TypeToJSON(
  object: ButtonData_Styles_Background_Type
): string {
  switch (object) {
    case ButtonData_Styles_Background_Type.COLOR:
      return "COLOR";
    case ButtonData_Styles_Background_Type.GRADIENT:
      return "GRADIENT";
    default:
      return "UNKNOWN";
  }
}

const baseButtonData: object = { type: ButtonData_Type.LINK };

export const ButtonData = {
  fromJSON(object: any): ButtonData {
    const message = { ...baseButtonData } as ButtonData;
    message.containerData =
      object.containerData !== undefined && object.containerData !== null
        ? PluginContainerData.fromJSON(object.containerData)
        : undefined;
    message.type =
      object.type !== undefined && object.type !== null
        ? buttonData_TypeFromJSON(object.type)
        : ButtonData_Type.LINK;
    message.styles =
      object.styles !== undefined && object.styles !== null
        ? ButtonData_Styles.fromJSON(object.styles)
        : undefined;
    message.text =
      object.text !== undefined && object.text !== null
        ? String(object.text)
        : undefined;
    message.link =
      object.link !== undefined && object.link !== null
        ? Link.fromJSON(object.link)
        : undefined;
    message.animation =
      object.animation !== undefined && object.animation !== null
        ? Animation.fromJSON(object.animation)
        : undefined;
    return message;
  },

  toJSON(message: ButtonData): unknown {
    const obj: any = {};
    message.containerData !== undefined &&
      (obj.containerData = message.containerData
        ? PluginContainerData.toJSON(message.containerData)
        : undefined);
    message.type !== undefined &&
      (obj.type = buttonData_TypeToJSON(message.type));
    message.styles !== undefined &&
      (obj.styles = message.styles
        ? ButtonData_Styles.toJSON(message.styles)
        : undefined);
    message.text !== undefined && (obj.text = message.text);
    message.link !== undefined &&
      (obj.link = message.link ? Link.toJSON(message.link) : undefined);
    message.animation !== undefined &&
      (obj.animation = message.animation
        ? Animation.toJSON(message.animation)
        : undefined);
    return obj;
  },
};

