/** Data for a smart block cell node. */
export interface SmartBlockCellData {
  /** Optional label text for the cell (e.g., for stats variants). */
  label?: string;
  /** Shape file details. */
  shape?: Media;
  /** Border color of the cell. */
  borderColor?: string;
  /** Border width in pixels. */
  borderWidth?: number;
  /** Border radius in pixels. */
  borderRadius?: number;
  /** The type of the parent smart block (must match parent). */
  type: SmartBlockData_Type;
  /** Accent color for non-background variants (e.g., line, bullet, label color). */
  accentColor?: string;
  /** Background color for background-based variants (SOLID_BOXES, SOLID_BOXES_ALTERNATING, SOLID_JOINED_BOXES). */
  backgroundColor?: string;
  /** Shape fill color as a hexadecimal value. */
  shapeColor?: string;
}

const baseSmartBlockData: object = {
  type: SmartBlockData_Type.SOLID_BOXES,
  columnSize: SmartBlockData_ColumnSize.SMALL,
};

export const SmartBlockData = {
  fromJSON(object: any): SmartBlockData {
    const message = { ...baseSmartBlockData } as SmartBlockData;
    message.type =
      object.type !== undefined && object.type !== null
        ? smartBlockData_TypeFromJSON(object.type)
        : SmartBlockData_Type.SOLID_BOXES;
    message.orientation =
      object.orientation !== undefined && object.orientation !== null
        ? String(object.orientation)
        : undefined;
    message.columnSize =
      object.columnSize !== undefined && object.columnSize !== null
        ? smartBlockData_ColumnSizeFromJSON(object.columnSize)
        : SmartBlockData_ColumnSize.SMALL;
    message.borderColor =
      object.borderColor !== undefined && object.borderColor !== null
        ? String(object.borderColor)
        : undefined;
    message.borderWidth =
      object.borderWidth !== undefined && object.borderWidth !== null
        ? Number(object.borderWidth)
        : undefined;
    message.borderRadius =
      object.borderRadius !== undefined && object.borderRadius !== null
        ? Number(object.borderRadius)
        : undefined;
    message.animation =
      object.animation !== undefined && object.animation !== null
        ? Animation.fromJSON(object.animation)
        : undefined;
    return message;
  },

  toJSON(message: SmartBlockData): unknown {
    const obj: any = {};
    message.type !== undefined &&
      (obj.type = smartBlockData_TypeToJSON(message.type));
    message.orientation !== undefined &&
      (obj.orientation = message.orientation);
    message.columnSize !== undefined &&
      (obj.columnSize = smartBlockData_ColumnSizeToJSON(message.columnSize));
    message.borderColor !== undefined &&
      (obj.borderColor = message.borderColor);
    message.borderWidth !== undefined &&
      (obj.borderWidth = message.borderWidth);
    message.borderRadius !== undefined &&
      (obj.borderRadius = message.borderRadius);
    message.animation !== undefined &&
      (obj.animation = message.animation
        ? Animation.toJSON(message.animation)
        : undefined);
    return obj;
  },
};

const baseSmartBlockCellData: object = {
  type: SmartBlockData_Type.SOLID_BOXES,
};

export const SmartBlockCellData = {
  fromJSON(object: any): SmartBlockCellData {
    const message = { ...baseSmartBlockCellData } as SmartBlockCellData;
    message.label =
      object.label !== undefined && object.label !== null
        ? String(object.label)
        : undefined;
    message.shape =
      object.shape !== undefined && object.shape !== null
        ? Media.fromJSON(object.shape)
        : undefined;
    message.borderColor =
      object.borderColor !== undefined && object.borderColor !== null
        ? String(object.borderColor)
        : undefined;
    message.borderWidth =
      object.borderWidth !== undefined && object.borderWidth !== null
        ? Number(object.borderWidth)
        : undefined;
    message.borderRadius =
      object.borderRadius !== undefined && object.borderRadius !== null
        ? Number(object.borderRadius)
        : undefined;
    message.type =
      object.type !== undefined && object.type !== null
        ? smartBlockData_TypeFromJSON(object.type)
        : SmartBlockData_Type.SOLID_BOXES;
    message.accentColor =
      object.accentColor !== undefined && object.accentColor !== null
        ? String(object.accentColor)
        : undefined;
    message.backgroundColor =
      object.backgroundColor !== undefined && object.backgroundColor !== null
        ? String(object.backgroundColor)
        : undefined;
    message.shapeColor =
      object.shapeColor !== undefined && object.shapeColor !== null
        ? String(object.shapeColor)
        : undefined;
    return message;
  },

  toJSON(message: SmartBlockCellData): unknown {
    const obj: any = {};
    message.label !== undefined && (obj.label = message.label);
    message.shape !== undefined &&
      (obj.shape = message.shape ? Media.toJSON(message.shape) : undefined);
    message.borderColor !== undefined &&
      (obj.borderColor = message.borderColor);
    message.borderWidth !== undefined &&
      (obj.borderWidth = message.borderWidth);
    message.borderRadius !== undefined &&
      (obj.borderRadius = message.borderRadius);
    message.type !== undefined &&
      (obj.type = smartBlockData_TypeToJSON(message.type));
    message.accentColor !== undefined &&
      (obj.accentColor = message.accentColor);
    message.backgroundColor !== undefined &&
      (obj.backgroundColor = message.backgroundColor);
    message.shapeColor !== undefined && (obj.shapeColor = message.shapeColor);
    return obj;
  },
};
