import { SketchData_Variant } from './decoration_sketch.enums.js';
/* eslint-disable */
export interface SketchData {
  /** The sketch annotation variant to draw over the text. */
  variant: SketchData_Variant;
  /** Annotation color. Defaults to the theme action color. */
  color?: string;
  /** Whether the annotation animates on first paint. Defaults to `true`. */
  animate?: boolean;
}

export function sketchData_VariantFromJSON(object: any): SketchData_Variant {
  switch (object) {
    case 0:
    case "UNDERLINE":
      return SketchData_Variant.UNDERLINE;
    case 1:
    case "BOX":
      return SketchData_Variant.BOX;
    case 2:
    case "CIRCLE":
      return SketchData_Variant.CIRCLE;
    case 3:
    case "HIGHLIGHT":
      return SketchData_Variant.HIGHLIGHT;
    case 4:
    case "STRIKETHROUGH":
      return SketchData_Variant.STRIKETHROUGH;
    case 5:
    case "CROSSED_OFF":
      return SketchData_Variant.CROSSED_OFF;
    case -1:
    case "UNRECOGNIZED":
    default:
      return SketchData_Variant.UNRECOGNIZED;
  }
}

export function sketchData_VariantToJSON(object: SketchData_Variant): string {
  switch (object) {
    case SketchData_Variant.UNDERLINE:
      return "UNDERLINE";
    case SketchData_Variant.BOX:
      return "BOX";
    case SketchData_Variant.CIRCLE:
      return "CIRCLE";
    case SketchData_Variant.HIGHLIGHT:
      return "HIGHLIGHT";
    case SketchData_Variant.STRIKETHROUGH:
      return "STRIKETHROUGH";
    case SketchData_Variant.CROSSED_OFF:
      return "CROSSED_OFF";
    default:
      return "UNKNOWN";
  }
}

const baseSketchData: object = { variant: SketchData_Variant.UNDERLINE };

export const SketchData = {
  fromJSON(object: any): SketchData {
    const message = { ...baseSketchData } as SketchData;
    message.variant =
      object.variant !== undefined && object.variant !== null
        ? sketchData_VariantFromJSON(object.variant)
        : SketchData_Variant.UNDERLINE;
    message.color =
      object.color !== undefined && object.color !== null
        ? String(object.color)
        : undefined;
    message.animate =
      object.animate !== undefined && object.animate !== null
        ? Boolean(object.animate)
        : undefined;
    return message;
  },

  toJSON(message: SketchData): unknown {
    const obj: any = {};
    message.variant !== undefined &&
      (obj.variant = sketchData_VariantToJSON(message.variant));
    message.color !== undefined && (obj.color = message.color);
    message.animate !== undefined && (obj.animate = message.animate);
    return obj;
  },
};
