/* eslint-disable */
import { Animation } from './animation.js';

export interface BlockquoteData {
  /** Indentation level from 1-4. */
  indentation: number;
  /** Node animation. */
  animation?: Animation;
}

const baseBlockquoteData: object = { indentation: 0 };

export const BlockquoteData = {
  fromJSON(object: any): BlockquoteData {
    const message = { ...baseBlockquoteData } as BlockquoteData;
    message.indentation =
      object.indentation !== undefined && object.indentation !== null
        ? Number(object.indentation)
        : 0;
    message.animation =
      object.animation !== undefined && object.animation !== null
        ? Animation.fromJSON(object.animation)
        : undefined;
    return message;
  },

  toJSON(message: BlockquoteData): unknown {
    const obj: any = {};
    message.indentation !== undefined &&
      (obj.indentation = Math.round(message.indentation));
    message.animation !== undefined &&
      (obj.animation = message.animation
        ? Animation.toJSON(message.animation)
        : undefined);
    return obj;
  },
};
