export interface LayoutData {
  /**
   * Deprecated: Use `background` instead.
   *
   * @deprecated
   */
  backgroundColor?: string;
  /** Background image. */
  backgroundImage?: LayoutData_BackgroundImage;
  /** Border color as a hexadecimal value. */
  borderColor?: string;
  /** Border width in pixels. */
  borderWidth?: number;
  /** Border radius in pixels. */
  borderRadius?: number;
  /**
   * Deprecated: Use `backdrop` instead.
   *
   * @deprecated
   */
  backdropColor?: string;
  /** Backdrop image. */
  backdropImage?: LayoutData_BackgroundImage;
  /** Backdrop top padding. */
  backdropPaddingTop?: number;
  /** Backdrop bottom padding */
  backdropPaddingBottom?: number;
  /** Horizontal and vertical gap between columns */
  gap?: number;
  /** Padding in pixels for cells. Follows CSS order: top, right, bottom, left */
  cellPadding: number[];
  /** Vertical alignment for the cell's items. */
  cellVerticalAlignment: LayoutData_VerticalAlignment_Alignment;
  /** Responsiveness behaviour of columns when responsiveness applies. Either stacks or wrappers. */
  responsivenessBehaviour: LayoutData_ResponsivenessBehaviour;
  /** Size in pixels when responsiveness_behaviour applies */
  responsivenessBreakpoint?: number;
  /** Styling for the layout's container. */
  containerData?: PluginContainerData;
  /** Defines where selected design propertied applies to */
  designTarget: LayoutData_DesignTarget;
  /** Banner configuration. When present, this layout is attached to a document edge (top or bottom). */
  banner?: LayoutData_Banner;
  /** Background styling (color or gradient). */
  background?: LayoutData_Background;
  /** Backdrop styling (color or gradient). */
  backdrop?: LayoutData_Backdrop;
  /** Node animation. */
  animation?: Animation;
}

export function layoutData_ImagePositionFromJSON(
  object: any
): LayoutData_ImagePosition {
  switch (object) {
    case 0:
    case "CENTER":
      return LayoutData_ImagePosition.CENTER;
    case 1:
    case "CENTER_LEFT":
      return LayoutData_ImagePosition.CENTER_LEFT;
    case 2:
    case "CENTER_RIGHT":
      return LayoutData_ImagePosition.CENTER_RIGHT;
    case 3:
    case "TOP":
      return LayoutData_ImagePosition.TOP;
    case 4:
    case "TOP_LEFT":
      return LayoutData_ImagePosition.TOP_LEFT;
    case 5:
    case "TOP_RIGHT":
      return LayoutData_ImagePosition.TOP_RIGHT;
    case 6:
    case "BOTTOM":
      return LayoutData_ImagePosition.BOTTOM;
    case 7:
    case "BOTTOM_LEFT":
      return LayoutData_ImagePosition.BOTTOM_LEFT;
    case 8:
    case "BOTTOM_RIGHT":
      return LayoutData_ImagePosition.BOTTOM_RIGHT;
    case -1:
    case "UNRECOGNIZED":
    default:
      return LayoutData_ImagePosition.UNRECOGNIZED;
  }
}

export function layoutData_ImagePositionToJSON(
  object: LayoutData_ImagePosition
): string {
  switch (object) {
    case LayoutData_ImagePosition.CENTER:
      return "CENTER";
    case LayoutData_ImagePosition.CENTER_LEFT:
      return "CENTER_LEFT";
    case LayoutData_ImagePosition.CENTER_RIGHT:
      return "CENTER_RIGHT";
    case LayoutData_ImagePosition.TOP:
      return "TOP";
    case LayoutData_ImagePosition.TOP_LEFT:
      return "TOP_LEFT";
    case LayoutData_ImagePosition.TOP_RIGHT:
      return "TOP_RIGHT";
    case LayoutData_ImagePosition.BOTTOM:
      return "BOTTOM";
    case LayoutData_ImagePosition.BOTTOM_LEFT:
      return "BOTTOM_LEFT";
    case LayoutData_ImagePosition.BOTTOM_RIGHT:
      return "BOTTOM_RIGHT";
    default:
      return "UNKNOWN";
  }
}

