const baseLayoutData: object = {
  cellPadding: 0,
  cellVerticalAlignment: LayoutData_VerticalAlignment_Alignment.TOP,
  responsivenessBehaviour: LayoutData_ResponsivenessBehaviour.STACK,
  designTarget: LayoutData_DesignTarget.LAYOUT,
};

export const LayoutData = {
  fromJSON(object: any): LayoutData {
    const message = { ...baseLayoutData } as LayoutData;
    message.backgroundColor =
      object.backgroundColor !== undefined && object.backgroundColor !== null
        ? String(object.backgroundColor)
        : undefined;
    message.backgroundImage =
      object.backgroundImage !== undefined && object.backgroundImage !== null
        ? LayoutData_BackgroundImage.fromJSON(object.backgroundImage)
        : undefined;
    message.borderColor =
      object.borderColor !== undefined && object.borderColor !== null
        ? String(object.borderColor)
        : undefined;
    message.borderWidth =
      object.borderWidth !== undefined && object.borderWidth !== null
        ? Number(object.borderWidth)
        : undefined;
    message.borderRadius =
      object.borderRadius !== undefined && object.borderRadius !== null
        ? Number(object.borderRadius)
        : undefined;
    message.backdropColor =
      object.backdropColor !== undefined && object.backdropColor !== null
        ? String(object.backdropColor)
        : undefined;
    message.backdropImage =
      object.backdropImage !== undefined && object.backdropImage !== null
        ? LayoutData_BackgroundImage.fromJSON(object.backdropImage)
        : undefined;
    message.backdropPaddingTop =
      object.backdropPaddingTop !== undefined &&
      object.backdropPaddingTop !== null
        ? Number(object.backdropPaddingTop)
        : undefined;
    message.backdropPaddingBottom =
      object.backdropPaddingBottom !== undefined &&
      object.backdropPaddingBottom !== null
        ? Number(object.backdropPaddingBottom)
        : undefined;
    message.gap =
      object.gap !== undefined && object.gap !== null
        ? Number(object.gap)
        : undefined;
    message.cellPadding = (object.cellPadding ?? []).map((e: any) => Number(e));
    message.cellVerticalAlignment =
      object.cellVerticalAlignment !== undefined &&
      object.cellVerticalAlignment !== null
        ? layoutData_VerticalAlignment_AlignmentFromJSON(
            object.cellVerticalAlignment
          )
        : LayoutData_VerticalAlignment_Alignment.TOP;
    message.responsivenessBehaviour =
      object.responsivenessBehaviour !== undefined &&
      object.responsivenessBehaviour !== null
        ? layoutData_ResponsivenessBehaviourFromJSON(
            object.responsivenessBehaviour
          )
        : LayoutData_ResponsivenessBehaviour.STACK;
    message.responsivenessBreakpoint =
      object.responsivenessBreakpoint !== undefined &&
      object.responsivenessBreakpoint !== null
        ? Number(object.responsivenessBreakpoint)
        : undefined;
    message.containerData =
      object.containerData !== undefined && object.containerData !== null
        ? PluginContainerData.fromJSON(object.containerData)
        : undefined;
    message.designTarget =
      object.designTarget !== undefined && object.designTarget !== null
        ? layoutData_DesignTargetFromJSON(object.designTarget)
        : LayoutData_DesignTarget.LAYOUT;
    message.banner =
      object.banner !== undefined && object.banner !== null
        ? LayoutData_Banner.fromJSON(object.banner)
        : undefined;
    message.background =
      object.background !== undefined && object.background !== null
        ? LayoutData_Background.fromJSON(object.background)
        : undefined;
    message.backdrop =
      object.backdrop !== undefined && object.backdrop !== null
        ? LayoutData_Backdrop.fromJSON(object.backdrop)
        : undefined;
    message.animation =
      object.animation !== undefined && object.animation !== null
        ? Animation.fromJSON(object.animation)
        : undefined;
    return message;
  },

  toJSON(message: LayoutData): unknown {
    const obj: any = {};
    message.backgroundColor !== undefined &&
      (obj.backgroundColor = message.backgroundColor);
    message.backgroundImage !== undefined &&
      (obj.backgroundImage = message.backgroundImage
        ? LayoutData_BackgroundImage.toJSON(message.backgroundImage)
        : undefined);
    message.borderColor !== undefined &&
      (obj.borderColor = message.borderColor);
    message.borderWidth !== undefined &&
      (obj.borderWidth = message.borderWidth);
    message.borderRadius !== undefined &&
      (obj.borderRadius = message.borderRadius);
    message.backdropColor !== undefined &&
      (obj.backdropColor = message.backdropColor);
    message.backdropImage !== undefined &&
      (obj.backdropImage = message.backdropImage
        ? LayoutData_BackgroundImage.toJSON(message.backdropImage)
        : undefined);
    message.backdropPaddingTop !== undefined &&
      (obj.backdropPaddingTop = message.backdropPaddingTop);
    message.backdropPaddingBottom !== undefined &&
      (obj.backdropPaddingBottom = message.backdropPaddingBottom);
    message.gap !== undefined && (obj.gap = message.gap);
    if (message.cellPadding) {
      obj.cellPadding = message.cellPadding.map((e) => Math.round(e));
    } else {
      obj.cellPadding = [];
    }
    message.cellVerticalAlignment !== undefined &&
      (obj.cellVerticalAlignment = layoutData_VerticalAlignment_AlignmentToJSON(
        message.cellVerticalAlignment
      ));
    message.responsivenessBehaviour !== undefined &&
      (obj.responsivenessBehaviour = layoutData_ResponsivenessBehaviourToJSON(
        message.responsivenessBehaviour
      ));
    message.responsivenessBreakpoint !== undefined &&
      (obj.responsivenessBreakpoint = message.responsivenessBreakpoint);
    message.containerData !== undefined &&
      (obj.containerData = message.containerData
        ? PluginContainerData.toJSON(message.containerData)
        : undefined);
    message.designTarget !== undefined &&
      (obj.designTarget = layoutData_DesignTargetToJSON(message.designTarget));
    message.banner !== undefined &&
      (obj.banner = message.banner
        ? LayoutData_Banner.toJSON(message.banner)
        : undefined);
    message.background !== undefined &&
      (obj.background = message.background
        ? LayoutData_Background.toJSON(message.background)
        : undefined);
    message.backdrop !== undefined &&
      (obj.backdrop = message.backdrop
        ? LayoutData_Backdrop.toJSON(message.backdrop)
        : undefined);
    message.animation !== undefined &&
      (obj.animation = message.animation
        ? Animation.toJSON(message.animation)
        : undefined);
    return obj;
  },
};

