export const LayoutData_BackgroundImage = {
  fromJSON(object: any): LayoutData_BackgroundImage {
    const message = {
      ...baseLayoutData_BackgroundImage,
    } as LayoutData_BackgroundImage;
    message.media =
      object.media !== undefined && object.media !== null
        ? Media.fromJSON(object.media)
        : undefined;
    message.opacity =
      object.opacity !== undefined && object.opacity !== null
        ? Number(object.opacity)
        : undefined;
    message.scaling =
      object.scaling !== undefined && object.scaling !== null
        ? layoutData_ImageScaling_ScalingFromJSON(object.scaling)
        : LayoutData_ImageScaling_Scaling.AUTO;
    message.position =
      object.position !== undefined && object.position !== null
        ? layoutData_ImagePositionFromJSON(object.position)
        : LayoutData_ImagePosition.CENTER;
    message.blur =
      object.blur !== undefined && object.blur !== null
        ? Number(object.blur)
        : undefined;
    message.overlay =
      object.overlay !== undefined && object.overlay !== null
        ? LayoutData_Background.fromJSON(object.overlay)
        : undefined;
    return message;
  },

  toJSON(message: LayoutData_BackgroundImage): unknown {
    const obj: any = {};
    message.media !== undefined &&
      (obj.media = message.media ? Media.toJSON(message.media) : undefined);
    message.opacity !== undefined && (obj.opacity = message.opacity);
    message.scaling !== undefined &&
      (obj.scaling = layoutData_ImageScaling_ScalingToJSON(message.scaling));
    message.position !== undefined &&
      (obj.position = layoutData_ImagePositionToJSON(message.position));
    message.blur !== undefined && (obj.blur = message.blur);
    message.overlay !== undefined &&
      (obj.overlay = message.overlay
        ? LayoutData_Background.toJSON(message.overlay)
        : undefined);
    return obj;
  },
};

