const baseGalleryData: object = {};

export const GalleryData = {
  fromJSON(object: any): GalleryData {
    const message = { ...baseGalleryData } as GalleryData;
    message.containerData =
      object.containerData !== undefined && object.containerData !== null
        ? PluginContainerData.fromJSON(object.containerData)
        : undefined;
    message.items = (object.items ?? []).map((e: any) =>
      GalleryData_Item.fromJSON(e)
    );
    message.options =
      object.options !== undefined && object.options !== null
        ? GalleryOptions.fromJSON(object.options)
        : undefined;
    message.disableExpand =
      object.disableExpand !== undefined && object.disableExpand !== null
        ? Boolean(object.disableExpand)
        : undefined;
    message.disableDownload =
      object.disableDownload !== undefined && object.disableDownload !== null
        ? Boolean(object.disableDownload)
        : undefined;
    message.animation =
      object.animation !== undefined && object.animation !== null
        ? Animation.fromJSON(object.animation)
        : undefined;
    return message;
  },

  toJSON(message: GalleryData): unknown {
    const obj: any = {};
    message.containerData !== undefined &&
      (obj.containerData = message.containerData
        ? PluginContainerData.toJSON(message.containerData)
        : undefined);
    if (message.items) {
      obj.items = message.items.map((e) =>
        e ? GalleryData_Item.toJSON(e) : undefined
      );
    } else {
      obj.items = [];
    }
    message.options !== undefined &&
      (obj.options = message.options
        ? GalleryOptions.toJSON(message.options)
        : undefined);
    message.disableExpand !== undefined &&
      (obj.disableExpand = message.disableExpand);
    message.disableDownload !== undefined &&
      (obj.disableDownload = message.disableDownload);
    message.animation !== undefined &&
      (obj.animation = message.animation
        ? Animation.toJSON(message.animation)
        : undefined);
    return obj;
  },
};

