/* eslint-disable */
export interface MentionData {
  /** The mentioned user's name. */
  name: string;
  /** The version of the user's name that appears after the `@` character in the mention. */
  slug: string;
  /** Mentioned user's ID. */
  id?: string;
  /** The kind of entity the mention refers to. Any value is accepted, and it's usually used to mark a mention as a group mention (for example, `group`). When empty, the mention refers to a member. */
  type?: string;
}

const baseMentionData: object = { name: "", slug: "" };

export const MentionData = {
  fromJSON(object: any): MentionData {
    const message = { ...baseMentionData } as MentionData;
    message.name =
      object.name !== undefined && object.name !== null
        ? String(object.name)
        : "";
    message.slug =
      object.slug !== undefined && object.slug !== null
        ? String(object.slug)
        : "";
    message.id =
      object.id !== undefined && object.id !== null
        ? String(object.id)
        : undefined;
    message.type =
      object.type !== undefined && object.type !== null
        ? String(object.type)
        : undefined;
    return message;
  },

  toJSON(message: MentionData): unknown {
    const obj: any = {};
    message.name !== undefined && (obj.name = message.name);
    message.slug !== undefined && (obj.slug = message.slug);
    message.id !== undefined && (obj.id = message.id);
    message.type !== undefined && (obj.type = message.type);
    return obj;
  },
};
