/* eslint-disable */
import { Animation } from './animation.js';

export interface OrderedListData {
  /** Indentation level from 0-4. */
  indentation: number;
  /** Offset level from 0-4. */
  offset?: number;
  /** List start number. */
  start?: number;
  /** Node animation. */
  animation?: Animation;
}

export interface BulletedListData {
  /** Indentation level from 0-4. */
  indentation: number;
  /** Offset level from 0-4. */
  offset?: number;
  /** Node animation. */
  animation?: Animation;
}

export interface CheckboxListData {
  /** Indentation level from 0-4. */
  indentation: number;
  /** Offset level from 0-4. */
  offset?: number;
  /** Node animation. */
  animation?: Animation;
}

export interface ListItemNodeData {
  /** Checkbox list item state. Defaults to `false`. */
  checked?: boolean;
  /** Node animation. */
  animation?: Animation;
}

const baseOrderedListData: object = { indentation: 0 };

export const OrderedListData = {
  fromJSON(object: any): OrderedListData {
    const message = { ...baseOrderedListData } as OrderedListData;
    message.indentation =
      object.indentation !== undefined && object.indentation !== null
        ? Number(object.indentation)
        : 0;
    message.offset =
      object.offset !== undefined && object.offset !== null
        ? Number(object.offset)
        : undefined;
    message.start =
      object.start !== undefined && object.start !== null
        ? Number(object.start)
        : undefined;
    message.animation =
      object.animation !== undefined && object.animation !== null
        ? Animation.fromJSON(object.animation)
        : undefined;
    return message;
  },

  toJSON(message: OrderedListData): unknown {
    const obj: any = {};
    message.indentation !== undefined &&
      (obj.indentation = Math.round(message.indentation));
    message.offset !== undefined && (obj.offset = message.offset);
    message.start !== undefined && (obj.start = message.start);
    message.animation !== undefined &&
      (obj.animation = message.animation
        ? Animation.toJSON(message.animation)
        : undefined);
    return obj;
  },
};

