/** List style. */
export enum TocData_ListStyle {
  /** PLAIN - No markers (default) */
  PLAIN = "PLAIN",
  /** NUMBERED - Numbered list */
  NUMBERED = "NUMBERED",
  /** LETTERS - Alphabetic letters */
  LETTERS = "LETTERS",
  /** ROMAN - Roman numerals */
  ROMAN = "ROMAN",
  /** BULLETED - Bulleted list */
  BULLETED = "BULLETED",
  /** ALPHABETICAL_INDEX - Alphabetical index */
  ALPHABETICAL_INDEX = "ALPHABETICAL_INDEX",
  /** ALPHABETICAL_INDEX_COMPACT - Alphabetical index (compact top-row only) */
  ALPHABETICAL_INDEX_COMPACT = "ALPHABETICAL_INDEX_COMPACT",
  UNRECOGNIZED = "UNRECOGNIZED",
}

/** Indentation style. */
export enum TocData_Indentation {
  /** NESTED - Sub-headings indented under parents (default) */
  NESTED = "NESTED",
  /** FLAT - All items at the same level */
  FLAT = "FLAT",
  UNRECOGNIZED = "UNRECOGNIZED",
}